                String key="@"+selected.optString("id");int w=getSurfaceHolder().getSurfaceFrame().width(),h=getSurfaceHolder().getSurfaceFrame().height();if(w<=0||h<=0){handler.postDelayed(this,100);return;}
                if(!key.equals(loaded)||player==null){releaseMedia();surface=PAGSurface.FromSurface(getSurfaceHolder().getSurface());player=new PAGPlayer();player.setSurface(surface);PAGComposition composition=PAGComposition.Make(w,h);compositionLayer=PAGImageLayer.Make(w,h,60000000L);compositionStamp=-1;composition.addLayer(compositionLayer);player.setComposition(composition);loaded=key;}
