        public void onApplyWindowInsets(android.view.WindowInsets insets){super.onApplyWindowInsets(insets);cameraRight=0;android.view.DisplayCutout cutout=insets.getDisplayCutout();if(cutout!=null)for(android.graphics.Rect r:cutout.getBoundingRects())if(r.left==0)cameraRight=Math.max(cameraRight,r.right);}
        public void onCreate(SurfaceHolder holder){super.onCreate(holder);setTouchEventsEnabled(true);}
        public void onSurfaceCreated(SurfaceHolder holder){super.onSurfaceCreated(holder);ready=true;handler.removeCallbacks(frame);if(visible)handler.post(frame);}
        public void onSurfaceChanged(SurfaceHolder h,int format,int width,int height){super.onSurfaceChanged(h,format,width,height);if(player!=null){releaseMedia();loaded="";}handler.removeCallbacks(frame);if(visible&&ready)handler.post(frame);}
