        public void onSensorChanged(android.hardware.SensorEvent event){if(event.sensor.getType()==android.hardware.Sensor.TYPE_STEP_DETECTOR){Pets.state.sensorStep(event.timestamp,SystemClock.elapsedRealtime());StepStore.step(PetWallpaper.this,event.timestamp);}else if(event.sensor.getType()==android.hardware.Sensor.TYPE_ACCELEROMETER){Pets.tiltX=Pets.tiltX*.85f+event.values[0]/9.81f*.15f;Pets.tiltY=Pets.tiltY*.85f+event.values[1]/9.81f*.15f;}}
        public void onAccuracyChanged(android.hardware.Sensor sensor,int accuracy){}
        public void onTouchEvent(android.view.MotionEvent e){super.onTouchEvent(e);if(e.getAction()==android.view.MotionEvent.ACTION_UP){if(Pets.current(PetWallpaper.this).optString("kind").equals("composition")){android.graphics.Rect bounds=getSurfaceHolder().getSurfaceFrame();compositionStamp=-1;compositionRenderer.touch(e.getX()/Math.max(1,bounds.width()),e.getY()/Math.max(1,bounds.height()),SystemClock.elapsedRealtime());}else if(Pets.current(PetWallpaper.this).optString("kind").equals("reactive"))Pets.override(PetWallpaper.this,12+(int)(SystemClock.elapsedRealtime()%3),4500);else {org.json.JSONObject clips=Pets.current(PetWallpaper.this).optJSONObject("clips");if(clips!=null&&clips.length()>0)Pets.choose(PetWallpaper.this,(Pets.scene+1)%clips.length());}}}
